<?php
include 'config.php';
require_once __DIR__.'/includes/tvs_public_helpers.php';
$active='noticias';
$id=$_GET['id']??'';
$newsFile='data/noticias.json';
$news=tvs_json($newsFile); if(!is_array($news)) $news=[];
$n=null; $idx=null;
foreach($news as $k=>$item){ if((string)($item['id']??'')===(string)$id){ $n=$item; $idx=$k; break; } }
if(!$n){ http_response_code(404); echo 'Notícia não encontrada'; exit; }
$n=tvs_normalize_news_item($n);
$views=(int)($n['views']??0)+1;
if($idx!==null){ $news[$idx]['views']=$views; @file_put_contents($newsFile,json_encode($news,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)); }
$url=rtrim($site_url??'', '/').'/noticia.php?id='.urlencode($id);
$title=tvs_clean_source_suffix($n['title']??'TV Sumaré');
$body=tvs_expand_article_display($n,400);
$desc=tvs_excerpt_clean($n['meta_description']??$n['subtitle']??$n['summary']??$body,155);
$readTime=tvs_read_time($body);
$shareText=$title.' '.$url;
$img=tvs_display_image($n); $imgAbs=tvs_img_abs($img,$site_url??'');
$video=tvs_find_related_video($n);
$related=[]; foreach(tvs_prepare_public_news($news,30) as $r){ if(($r['id']??'')===($n['id']??'')) continue; if(($r['category']??'')===($n['category']??'') || ($r['city']??'')===($n['city']??'')) $related[]=$r; if(count($related)>=3) break; }
$paragraphs=array_values(array_filter(preg_split("/\n\s*\n/",trim($body))));
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=tvs_h($title)?> | TV Sumaré</title><meta name="description" content="<?=tvs_h($desc)?>"><link rel="canonical" href="<?=tvs_h($url)?>"><meta property="og:type" content="article"><meta property="og:title" content="<?=tvs_h($title)?>"><meta property="og:description" content="<?=tvs_h($desc)?>"><meta property="og:url" content="<?=tvs_h($url)?>"><?php if($imgAbs): ?><meta property="og:image" content="<?=tvs_h($imgAbs)?>"><?php endif; ?><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@type'=>'NewsArticle','headline'=>$title,'description'=>$desc,'image'=>$imgAbs?[$imgAbs]:[], 'datePublished'=>date('c', tvs_date_ts($n)), 'dateModified'=>date('c'), 'author'=>['@type'=>'Organization','name'=>$n['author']??'Redação TV Sumaré'], 'publisher'=>['@type'=>'Organization','name'=>'TV Sumaré','logo'=>['@type'=>'ImageObject','url'=>rtrim($site_url??'', '/').'/assets/logo-tv-sumare.jpeg']], 'mainEntityOfPage'=>$url],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?></script><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/style.css?v=homologacao-final"><link rel="stylesheet" href="assets/tvsumare-final-fixes.css?v=3"><style>.article-meta{display:flex;gap:10px;flex-wrap:wrap;color:#64748b;font-size:14px;margin-top:10px}.share{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.share a,.share button{border:0;border-radius:999px;padding:10px 14px;font-weight:800;text-decoration:none;background:#eef2ff;color:#0f2f68;cursor:pointer;font-family:inherit}.share .whats{background:#dcfce7;color:#166534}.share .face{background:#dbeafe;color:#1d4ed8}.share .tele{background:#e0f2fe;color:#0369a1}.share .copy{background:#fff7ed;color:#c2410c}.source-box{margin-top:26px;padding-top:18px;border-top:1px solid #e6edf8;font-size:14px;color:#64748b}.article-body{padding:30px;margin-top:22px;line-height:1.78;font-size:18px}.article-body p{margin:0 0 18px}.share-title{font-size:18px;margin-top:26px}.toast{display:none;margin-top:8px;color:#166534;font-weight:800}.article-ad{margin:24px 0;padding:22px;border:2px dashed #cbd5e1;border-radius:20px;text-align:center;background:#f8fafc}.related-video{margin:26px 0;padding:22px;border-radius:24px;background:#071f49;color:#fff}.related-video h2{margin:0 0 14px}.related-video video,.related-video iframe{width:100%;aspect-ratio:16/9;border:0;border-radius:18px;background:#000}.related-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin-top:14px}.related-card{display:block;text-decoration:none;color:inherit;border:1px solid #e2e8f0;border-radius:18px;overflow:hidden;background:#fff}.related-card img{width:100%;height:110px;object-fit:cover}.related-card div{padding:12px;font-weight:800}.no-public-image{margin:18px 0;padding:18px;border-left:5px solid #0f2f68;background:#f8fafc;border-radius:14px;color:#334155;font-weight:700}</style></head><body><?php include 'header.php'; ?>
<main class="container page-shell" style="max-width:980px">
  <div class="page-title"><span><?=tvs_h($n['city']??'Região')?> • <?=tvs_h($n['category']??'Notícias')?></span><h1><?=tvs_h($title)?></h1><p><?=tvs_h(tvs_excerpt_clean($n['subtitle']??$n['summary']??'',190))?></p><div class="article-meta"><span>🕒 <?=$readTime?> min de leitura</span><span>👁 <?=$views?> visualizações</span><span>📅 <?=tvs_h(date('d/m/Y', tvs_date_ts($n)))?></span><span>✍️ <?=tvs_h($n['author']??'Redação TV Sumaré')?></span></div></div>
  <div class="share" aria-label="Compartilhar notícia"><a class="whats" target="_blank" rel="noopener" href="https://api.whatsapp.com/send?text=<?=urlencode($shareText)?>">WhatsApp</a><a class="face" target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u=<?=urlencode($url)?>">Facebook</a><a class="tele" target="_blank" rel="noopener" href="https://t.me/share/url?url=<?=urlencode($url)?>&text=<?=urlencode($title)?>">Telegram</a><button class="copy" type="button" onclick="copyNewsLink()">Copiar link</button></div><div id="toast" class="toast">Link copiado com sucesso.</div>
  <?php if($img): ?><img src="<?=tvs_h($img)?>" onerror="this.src='assets/tvsumare-noticia-padrao.svg'" style="width:100%;border-radius:28px;max-height:500px;object-fit:cover;box-shadow:var(--shadow)" alt=""><?php if(!empty($n['image_credit']) && !tvs_is_category_asset($n['image']??'')): ?><div style="font-size:12px;color:#64748b;margin:8px 4px 0"><?=tvs_h($n['image_credit'])?></div><?php endif; ?><?php endif; ?>
  <?php if($video): $vurl=tvs_video_url($video); $embed=tvs_youtube_embed($vurl); ?><section class="related-video"><h2>▶ Assista ao vídeo desta reportagem</h2><?php if($embed): ?><iframe src="<?=tvs_h($embed)?>" allowfullscreen></iframe><?php elseif(preg_match('~\.mp4(\?|$)~i',$vurl)): ?><video controls playsinline src="<?=tvs_h($vurl)?>"></video><?php else: ?><a class="btn" href="<?=tvs_h($vurl)?>" target="_blank" rel="noopener">Abrir vídeo</a><?php endif; ?></section><?php endif; ?>
  <article class="news-card article-body">
    <?php foreach($paragraphs as $i=>$p): ?><p><?=nl2br(tvs_h($p))?></p><?php if($i===2): ?><div class="article-ad"><strong>ANUNCIE NA TV SUMARÉ</strong><br>Sua empresa pode aparecer aqui. <a href="anuncie.php">Conheça os planos comerciais</a>.</div><?php endif; ?><?php endforeach; ?>
    <?php if(!empty($n['source']) || !empty($n['source_url'])): ?><p class="source-box"><strong>Fonte consultada:</strong> <?php if(!empty($n['source_url'])): ?><a target="_blank" rel="noopener" href="<?=tvs_h($n['source_url'])?>"><?=tvs_h($n['source']??'Fonte original')?></a><?php else: ?><?=tvs_h($n['source'])?><?php endif; ?></p><?php endif; ?>
    <h3 class="share-title">Compartilhe esta notícia</h3><div class="share"><a class="whats" target="_blank" rel="noopener" href="https://api.whatsapp.com/send?text=<?=urlencode($shareText)?>">WhatsApp</a><a class="face" target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u=<?=urlencode($url)?>">Facebook</a><a class="tele" target="_blank" rel="noopener" href="https://t.me/share/url?url=<?=urlencode($url)?>&text=<?=urlencode($title)?>">Telegram</a></div>
  </article>
  <?php if($related): ?><section style="margin-top:28px"><div class="section-heading"><h2>Notícias relacionadas</h2><a href="noticias.php">Ver mais</a></div><div class="related-grid"><?php foreach($related as $r): $ri=tvs_display_image($r); ?><a class="related-card" href="<?=tvs_h(tvs_news_url($r))?>"><?php if($ri): ?><img src="<?=tvs_h($ri)?>" onerror="this.src='assets/tvsumare-noticia-padrao.svg'" alt=""><?php endif; ?><div><span class="category-tag"><?=tvs_h($r['category']??'Notícia')?></span><br><?=tvs_h(tvs_title($r['title']??'Sem título',80))?></div></a><?php endforeach; ?></div></section><?php endif; ?>
</main><script>function copyNewsLink(){var link=<?=json_encode($url)?>;if(navigator.clipboard){navigator.clipboard.writeText(link);}else{var t=document.createElement('textarea');t.value=link;document.body.appendChild(t);t.select();document.execCommand('copy');document.body.removeChild(t);}var toast=document.getElementById('toast');if(toast){toast.style.display='block';setTimeout(function(){toast.style.display='none'},2500);}}</script><?php include 'rodape.php'; ?></body></html>
